// Normalise both triggers to { user_id, ai_note_id, auth_uid, source }.
//  - Schedule trigger -> all null, source 'daily' -> batch over active users.
//  - Webhook callers:
//      * Supabase DB webhook on mobile_checkins INSERT -> body.record.app_user_id
//        (and/or body.record.auth_uid)
//      * SOAP & Note QA workflow (after a session note)  -> body.app_user_id
//        (preferred) or body.ai_note_id
//      * Anything app-side that only knows the Supabase auth id -> body.auth_uid
// A webhook call with no resolvable identifier is dropped, and the SQL only
// runs a batch when source === 'daily' — a malformed webhook can never
// accidentally re-rank everyone.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const results = [];
for (const item of $input.all()) {
  const j = item.json ?? {};
  const isWebhook = j.body !== undefined || j.headers !== undefined;
  const b = j.body ?? {};
  const rec = b.record ?? b;
  const userId = Number(rec.app_user_id ?? rec.user_id ?? NaN);
  const noteId = Number(rec.ai_note_id ?? NaN);
  const rawUid = String(rec.auth_uid ?? rec.authUid ?? '').trim();
  const authUid = UUID.test(rawUid) ? rawUid.toLowerCase() : null; // regex-validated -> safe to inline in SQL
  const src = (b.trigger ?? rec.trigger) === 'note' ? 'note' : 'checkin';
  if (Number.isInteger(userId) && userId > 0) {
    results.push({ json: { user_id: userId, ai_note_id: null, auth_uid: authUid, source: src } });
  } else if (Number.isInteger(noteId) && noteId > 0) {
    results.push({ json: { user_id: null, ai_note_id: noteId, auth_uid: null, source: 'note' } });
  } else if (authUid) {
    results.push({ json: { user_id: null, ai_note_id: null, auth_uid: authUid, source: 'checkin' } });
  } else if (!isWebhook) {
    results.push({ json: { user_id: null, ai_note_id: null, auth_uid: null, source: 'daily' } });
  }
}
return results;

// Merge three sources per user, tolerating failures in either optional one:
//  1. Gather (Supabase)          — app signals, candidates, fallback clinical copies
//  2. Clinical signals (legacy)  — LIVE notes + treatment plan (wins when present)
//  3. App context RPC (Supabase) — assessments, activity, safety flags
const results = [];
for (const item of $input.all()) {
  const base = $('Gather user signals + candidates').itemMatching(item.index)?.json ?? {};
  if (base.user_id == null) continue;

  let legacy = {};
  try { legacy = $('Clinical signals (legacy DB)').itemMatching(item.index)?.json ?? {}; } catch (e) {}
  const liveNotes = Array.isArray(legacy.session_notes_live) ? legacy.session_notes_live : [];
  const livePlan  = Array.isArray(legacy.treatment_plan_live) ? legacy.treatment_plan_live : [];

  let ctx = item.json?.app_ctx ?? null;
  if (typeof ctx === 'string') { try { ctx = JSON.parse(ctx); } catch (e) { ctx = null; } }
  if (!ctx || typeof ctx !== 'object' || item.json?.error) ctx = {};

  const hist = Array.isArray(ctx.assessment_history) ? ctx.assessment_history : [];
  const byInst = {};
  for (const h of hist) { (byInst[h.instrument] ??= []).push(h); }
  const latest = ctx.assessments_latest ?? {};
  const assessments = Object.entries(latest).map(([inst, v]) => {
    const seq = byInst[inst] ?? [];
    const prev = seq.length >= 2 ? seq[seq.length - 2] : null;
    const trend = prev == null || v.score == null ? 'first take'
      : v.score < prev.score ? `improving (was ${prev.score})`
      : v.score > prev.score ? `worsening (was ${prev.score})`
      : 'stable';
    return { instrument: inst, score: v.score, severity: v.severity, trend };
  });
  const flags = (ctx.safety_flags && typeof ctx.safety_flags === 'object') ? ctx.safety_flags : {};

  results.push({ json: {
    ...base,
    session_notes: liveNotes.length ? liveNotes : (base.session_notes ?? []),
    treatment_plan: livePlan.length ? livePlan : (base.treatment_plan ?? []),
    app_focus: ctx.focus ?? null,
    assessments,
    activity_7d: ctx.activity_7d ?? {},
    streak_days: ctx.gamification?.streak_days ?? null,
    safety_flags: flags,
    any_safety_flag: Object.values(flags).some(Boolean),
  }});
}
return results;

parameters.text:
=You are the recommendation engine for SPARx, IGNTD's recovery app built on Dr. Adi Jaffe's approach: compassionate, shame-free, strengths-based, meeting people exactly where they are.

USER CONTEXT
- Working on: {{ $json.addiction_label }}; self-reported focus: {{ JSON.stringify($json.app_focus) }}
- SAFETY FLAGS from their latest validated assessments (PHQ-9/GAD-7/PCL-5/AUDIT-C): {{ JSON.stringify($json.safety_flags) }}
- Validated assessment scores, latest per instrument, with trend vs previous take: {{ JSON.stringify($json.assessments) }}
- ACTIVE TREATMENT PLAN (clinician-approved goals and plan items — your PRIMARY steady-state signal; recommended content must serve these goals): {{ JSON.stringify($json.treatment_plan) }}
- CLINICAL SESSION NOTES from recent individual/group sessions (assessment, plan for next steps, tags, risk): {{ JSON.stringify($json.session_notes) }}
- Recent app check-ins, newest first (mood 0-100; 'used' = engaged in the behaviour): {{ JSON.stringify($json.recent_checkins) }}
- Earlier daily assessments (self-statement + emotions): {{ JSON.stringify($json.prod_checkins) }}
- Lowest Wheel of Life areas right now (0-10): {{ JSON.stringify($json.lowest_wheel_areas) }}
- Lessons they recently worked through: {{ JSON.stringify($json.recent_lessons) }}
- App activity, last 7 days (what they've actually been doing): {{ JSON.stringify($json.activity_7d) }}; current streak: {{ $json.streak_days }} days

CANDIDATE VIDEOS — the ONLY videos you may recommend (already excludes ones they've watched):
{{ JSON.stringify($json.candidates) }}

CANDIDATE LESSONS & WORKSHOPS — the ONLY lessons/workshops you may recommend:
{{ JSON.stringify($json.lesson_candidates) }}

TASK
Pick the 3 to 5 best videos, and up to 2 lessons/workshops, that meet this user where they are right now.

Rules:
- Use only snippet_id / lesson_id values that appear in the candidate lists. Never invent an id.
- Anchor picks in the signals, in priority order: (1) treatment-plan goals and session-note plan/next-steps, WHEN PRESENT; (2) latest check-in mood/struggles and assessment severity/trends — a slip ('used' = yes, amount 'more') gets shame-free relapse content, never punitive; a worsening instrument (e.g. GAD-7 climbing) gets content for that domain; (3) lowest wheel areas; (4) natural next step after recent lessons, not a repeat.
- ACUTE-STATE OVERRIDE: if ANY safety flag is true (self_harm above all), or the most recent check-in signals acute distress or crisis (very low mood, crisis-level struggles like hopelessness or self-harm-adjacent tags, or a heavy slip), TODAY'S state outranks everything above — pick stabilising, grounding, shame-free, self-compassion content first, and defer longer-term treatment-plan and skill-building goals to the remaining picks.
- MISSING DATA IS NEUTRAL: an empty treatment plan, empty session notes, or no assessments just means this client hasn't done those yet — it says NOTHING about them. Rank confidently on whatever signals exist. Never infer anything from absent data, never mention its absence, and never reduce the number or quality of picks because of it.
- ENGAGEMENT-AWARE: use activity_7d lightly — a heavy video-watcher can get a lesson nudge for depth; a lapsed streak gets one easy, low-effort re-entry pick. Never guilt-trip about inactivity.
- Prefer variety across the picks.
- If lesson_candidates is empty, return an empty lesson_recommendations array.
- If ALL signals are sparse (brand-new client), fall back to broadly useful foundational content and say so in the reason.
- reason: ONE warm, specific sentence in Adi's voice explaining why this content, for this user, today. It may be shown to the user.
- CONFIDENTIALITY: never quote, paraphrase, or reveal the existence of session notes, coaches' observations, the treatment plan, assessment names/scores, or safety flags in any reason. They inform WHAT you pick, never what you SAY. Reasons like "because your coach mentioned…", "as part of your treatment plan…", or "your anxiety score…" are forbidden; anchor the wording in the user's own check-ins or general growth instead.

