// Hallucination guard + provenance shaping.
// - Drop any id the model invented (must be in this user's candidate pools).
// - Cap videos at 5, lessons/workshops at 2.
// - Build the provenance rows (reason + the exact signal snapshot that drove
//   the pick) and pre-escape everything for safe SQL inlining.
const esc = (s) => String(s ?? '').replace(/'/g, "''");
const results = [];
for (const item of $input.all()) {
  const src = $('Merge app context').itemMatching(item.index)?.json ?? {};
  const out = item.json.output ?? item.json;
  const userId = Number(src.user_id);
  if (!Number.isInteger(userId)) continue;

  const videoPool = new Set((src.candidates ?? []).map((c) => Number(c.snippet_id)));
  const lessonPool = new Map((src.lesson_candidates ?? []).map((c) => [Number(c.lesson_id), c.content_type]));

  const videos = (out.video_recommendations ?? [])
    .map((r) => ({ id: Number(r.snippet_id), reason: String(r.reason ?? '').slice(0, 500) }))
    .filter((r) => Number.isInteger(r.id) && videoPool.has(r.id))
    .slice(0, 5);
  const lessons = (out.lesson_recommendations ?? [])
    .map((r) => ({ id: Number(r.lesson_id), reason: String(r.reason ?? '').slice(0, 500) }))
    .filter((r) => Number.isInteger(r.id) && lessonPool.has(r.id))
    .map((r) => ({ ...r, content_type: lessonPool.get(r.id) === 'workshop' ? 'workshop' : 'lesson' }))
    .slice(0, 2);
  if (!videos.length && !lessons.length) continue;

  // Explainability snapshot: the signals (NOT the candidate pools) fed to the model.
  const signals = {
    addiction: src.addiction_label,
    app_focus: src.app_focus,
    safety_flags: src.safety_flags,
    assessments: src.assessments,
    treatment_plan: src.treatment_plan,
    session_notes: (src.session_notes ?? []).map((n) => ({
      date: n.date, type: n.type, tags: n.tags, plan_next: n.plan_next, risk: n.risk })),
    recent_checkins: src.recent_checkins,
    prod_checkins: src.prod_checkins,
    lowest_wheel_areas: src.lowest_wheel_areas,
    recent_lessons: src.recent_lessons,
    activity_7d: src.activity_7d,
    streak_days: src.streak_days,
  };

  const ledger = [
    ...videos.map((v) => ({ content_type: 'snippet', content_id: v.id, reason: v.reason })),
    ...lessons.map((l) => ({ content_type: l.content_type, content_id: l.id, reason: l.reason })),
  ];

  results.push({
    json: {
      user_id: userId,
      source: String(src.source ?? 'daily'),
      has_videos: videos.length > 0,
      video_id_list: videos.map((v) => v.id).join(',') || '0',
      ledger_sql: esc(JSON.stringify(ledger)),
      signals_sql: esc(JSON.stringify(signals)),
    },
  });
}
return results;
